mapper.select:
select t.value_source as valueSource, t.curve_code as curveCode, t.CURVE_NAME as curveName, t.remark as remark, t.int_curve_type as intCurveType, t.CCY as ccy, '线性插值' as interMethod, 'A/365' as dayRules, '银行间交易日历' as calender, '起息日向后' as interestDateRule, '按年复利' as interestCalMethod, '年付' as interestFreq from MST_CURVE_DEF t
1=1
and t.CURVE_CODE = #{curveCode}
and t.CURVE_TYPE = #{curve_type}
and t.INT_CURVE_TYPE = #{intCurveType}
and t.CURVE_NAME LIKE CONCAT('%', CONCAT(#{curveName}, '%'))
and t.CURVE_SOURCE = #{curveSource}

		select
		CURVE_CODE curveCode,
		remark remark,
		INT_CURVE_TYPE as curveType
		from MST_CURVE_DEF

			1=1
-- 			 NVL(eff_status,'E') = #{effStatus,jdbcType=VARCHAR}

				and remark = #{curveName,jdbcType=VARCHAR}


				and t.curve_type = #{curve_type}
